/**
 * Work log — a per-day, per-project record of what was worked on.
 *
 * Every top-level turn of every session is folded into a work item. Items group
 * by working directory into projects, and a project carries the day's duration,
 * changed folders/files, and a short "what got solved" summary. The summary is
 * generated by the model from the day's items on demand (cached per day and
 * project) and is the ONLY prose the page shows: raw prompts and replies never
 * leave the host.
 *
 * Data lives in `$DSH_HOME/work-log/YYYY-MM-DD.json`. The Web panel reads a JSON
 * route; the agent reads and annotates the same data through the `work_log` tool.
 */
import { mkdir, readFile, readdir, rename, writeFile } from 'node:fs/promises'
import { homedir } from 'node:os'
import { basename, isAbsolute, join, relative } from 'node:path'

/** Stable Loader identity. */
const name = 'work-log'
/** The tool registry is a hard dependency; every other service is optional. */
const inject = ['tools']

const DEFAULT_DAYS = 14
const MAX_FILES_IN_ITEM = 40
const PROMPT_CHARS = 600
const REPLY_CHARS = 700
const FLUSH_DELAY_MS = 350
/** At most one wallet read per this interval, however often the page polls. */
const BALANCE_MIN_INTERVAL_MS = 5 * 60 * 1000
/** Backfill cap per live session at activation. */
const BACKFILL_EVENTS = 1500
/** One turn can never contribute more than this to a day's duration. */
const MAX_TURN_MS = 3 * 60 * 60 * 1000
/** An open turn only counts as live while it keeps producing events. */
const LIVE_TURN_MS = 3 * 60 * 1000
/** Upper bound on the model call that writes one project summary. */
const SUMMARY_MAX_TOKENS = 1500
/** Largest accepted request body on the summarize route. */
const MAX_BODY_BYTES = 16 * 1024
/** One summary call may not hang the route forever. */
const SUMMARY_TIMEOUT_MS = 60 * 1000

const ROOT_FOLDER = '（根目录）'
const OUTSIDE_FOLDER = '（工作目录外）'
const UNKNOWN_PROJECT = '（未记录目录）'

/** Zero-padded local calendar day of a timestamp. */
function localDay(time) {
  const date = new Date(time)
  const pad = (value) => String(value).padStart(2, '0')
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`
}

/** Local wall-clock time `HH:mm` of a timestamp. */
function clockTime(time) {
  const date = new Date(time)
  const pad = (value) => String(value).padStart(2, '0')
  return `${pad(date.getHours())}:${pad(date.getMinutes())}`
}

/** Collapse whitespace and clip to a readable length. */
function clip(text, max) {
  const flat = String(text ?? '').replace(/\s+/g, ' ').trim()
  if (flat.length <= max) return flat
  return `${flat.slice(0, max - 1)}…`
}

/** Concatenated text blocks of a message content array. */
function textOf(content) {
  if (!Array.isArray(content)) return ''
  let out = ''
  for (const block of content) {
    if (block && block.type === 'text' && typeof block.text === 'string') {
      out += (out === '' ? '' : ' ') + block.text
    }
  }
  return out
}

/** The folder that holds one changed path, relative to the session working directory. */
function folderOf(path, cwd) {
  let relativePath = String(path ?? '')
  if (isAbsolute(relativePath)) {
    if (typeof cwd !== 'string' || cwd === '') return OUTSIDE_FOLDER
    relativePath = relative(cwd, relativePath)
  }
  relativePath = relativePath.split('\\').join('/')
  if (relativePath.startsWith('..')) return OUTSIDE_FOLDER
  const slash = relativePath.lastIndexOf('/')
  if (slash < 0) return ROOT_FOLDER
  const folder = relativePath.slice(0, slash)
  return folder === '' || folder === '.' ? ROOT_FOLDER : folder
}

/** An empty day record. */
function emptyDay(date) {
  return { date, items: {}, notes: [], summaries: {} }
}

/** Total length of a set of possibly overlapping intervals. */
function unionMs(intervals) {
  const sorted = intervals
    .filter((interval) => interval[1] > interval[0])
    .sort((left, right) => left[0] - right[0])
  let total = 0
  let start = -Infinity
  let end = -Infinity
  for (const [from, to] of sorted) {
    if (from > end) {
      if (end > start) total += end - start
      start = from
      end = to
      continue
    }
    if (to > end) end = to
  }
  if (end > start) total += end - start
  return total
}

/** The bounded interval one work item covered; an unfinished turn ends at its last event. */
function intervalOf(item) {
  const from = item.startedAt
  const raw = item.endedAt ?? item.updatedAt ?? item.startedAt
  const to = Math.min(raw, from + MAX_TURN_MS)
  return [from, Math.max(from, to)]
}

/** Fold one day into the project-oriented payload the page renders. */
function dayView(day) {
  const projects = new Map()
  const allIntervals = []
  let turns = 0
  let files = 0
  let added = 0
  let deleted = 0

  for (const item of Object.values(day.items)) {
    const key = item.cwd === '' ? UNKNOWN_PROJECT : item.cwd
    let project = projects.get(key)
    if (project === undefined) {
      project = {
        key,
        name: key === UNKNOWN_PROJECT ? UNKNOWN_PROJECT : basename(key) || key,
        cwd: key,
        intervals: [],
        turns: 0,
        folders: new Map(),
        files: 0,
        added: 0,
        deleted: 0,
        firstAt: item.startedAt,
        lastAt: item.startedAt,
        lastUpdatedAt: item.updatedAt ?? item.startedAt,
      }
      projects.set(key, project)
    }
    const interval = intervalOf(item)
    project.intervals.push(interval)
    allIntervals.push(interval)
    project.turns += 1
    project.files += item.files ?? 0
    project.added += item.added ?? 0
    project.deleted += item.deleted ?? 0
    project.firstAt = Math.min(project.firstAt, item.startedAt)
    project.lastAt = Math.max(project.lastAt, item.startedAt)
    project.lastUpdatedAt = Math.max(project.lastUpdatedAt, item.updatedAt ?? item.startedAt)
    for (const [path, count] of Object.entries(item.folders ?? {})) {
      project.folders.set(path, (project.folders.get(path) ?? 0) + count)
    }
    turns += 1
    files += item.files ?? 0
    added += item.added ?? 0
    deleted += item.deleted ?? 0
  }

  const view = [...projects.values()]
    .map((project) => {
      const summary = day.summaries?.[project.key] ?? null
      return {
        key: project.key,
        name: project.name,
        cwd: project.cwd,
        ms: unionMs(project.intervals),
        turns: project.turns,
        firstClock: clockTime(project.firstAt),
        lastClock: clockTime(project.lastAt),
        lastAt: project.lastAt,
        lastUpdatedAt: project.lastUpdatedAt,
        files: project.files,
        added: project.added,
        deleted: project.deleted,
        folders: [...project.folders.entries()]
          .map(([path, count]) => ({ path, files: count }))
          .sort((left, right) => right.files - left.files || left.path.localeCompare(right.path)),
        summary: summary === null ? null : {
          bullets: summary.bullets,
          at: summary.at,
          turns: summary.turns,
          source: summary.source,
          stale: summary.turns !== project.turns || (summary.at ?? 0) < project.lastUpdatedAt,
        },
      }
    })
    .sort((left, right) => right.ms - left.ms || right.lastAt - left.lastAt)

  return {
    date: day.date,
    account: day.account === undefined ? null : {
      currency: day.account.currency,
      balance: day.account.current,
      wallets: day.account.wallets ?? [],
      bonus: day.account.bonus ?? [],
      spend: Math.max(0, Math.round((day.account.opening - day.account.current + (day.account.topUps ?? 0)) * 100) / 100),
      at: day.account.at,
    },
    running: Object.values(day.items).some((item) => item.endedAt === undefined
      && Date.now() - (item.updatedAt ?? item.startedAt) < LIVE_TURN_MS),
    totalMs: unionMs(allIntervals),
    totals: { projects: view.length, turns, files, added, deleted },
    projects: view,
    notes: [...day.notes].sort((left, right) => right.time - left.time),
  }
}

/** `2 小时 14 分` style duration. */
function formatDuration(ms) {
  if (!Number.isFinite(ms) || ms <= 0) return '0 分钟'
  const minutes = Math.round(ms / 60000)
  if (minutes < 1) return '不到 1 分钟'
  const hours = Math.floor(minutes / 60)
  const rest = minutes % 60
  if (hours === 0) return `${rest} 分钟`
  if (rest === 0) return `${hours} 小时`
  return `${hours} 小时 ${rest} 分`
}

/**
 * Register the work log: fold session activity into per-day files, serve the
 * project summary, generate project summaries with the model, and expose the
 * `work_log` tool.
 * @param ctx - host context with the tool registry.
 */
function apply(ctx) {
  const home = typeof process.env.DSH_HOME === 'string' && process.env.DSH_HOME !== ''
    ? process.env.DSH_HOME
    : join(homedir(), '.dsh')
  const dataDir = join(home, 'work-log')

  /** date -> day record, loaded on demand. */
  const days = new Map()
  /** date -> in-flight load, so concurrent first touches share one object. */
  const loading = new Map()
  /** sessionId -> { turn, startedAt, prompt, reply, messages } */
  const sessions = new Map()
  /** `${date}|${project}` -> in-flight summary generation. */
  const summarizing = new Map()
  const dirty = new Set()
  /** Last successful wallet read, so the page cannot hammer the account API. */
  let lastBalanceAt = 0
  /** One wallet read at a time, however many requests arrive together. */
  let balanceInFlight = null
  let timer = null
  let writing = null
  /** Monotonic suffix so two writers never share a temp file. */
  let writeSeq = 0

  const warn = (message, error) => {
    try {
      ctx.logger?.warn(`work-log: ${message} ${error instanceof Error ? error.message : String(error ?? '')}`)
    } catch {
      /* logging must never break recording */
    }
  }

  /** Load one day file once; a missing or corrupt file starts empty. */
  async function loadDay(date) {
    const cached = days.get(date)
    if (cached !== undefined) return cached
    const pending = loading.get(date)
    if (pending !== undefined) return pending
    const load = (async () => {
      const day = emptyDay(date)
      try {
        const raw = await readFile(join(dataDir, `${date}.json`), 'utf8')
        const parsed = JSON.parse(raw)
        if (parsed && typeof parsed === 'object') {
          for (const item of Object.values(parsed.items ?? {})) {
            if (item && typeof item === 'object' && typeof item.id === 'string') day.items[item.id] = item
          }
          if (Array.isArray(parsed.notes)) {
            day.notes = parsed.notes.filter((note) => note && typeof note.id === 'string')
          }
          if (parsed.summaries && typeof parsed.summaries === 'object') {
            day.summaries = parsed.summaries
          }
          if (parsed.account && typeof parsed.account === 'object') {
            day.account = parsed.account
          }
        }
      } catch (error) {
        if (error?.code !== 'ENOENT') warn(`could not read ${date}.json; starting a fresh day`, error)
      }
      days.set(date, day)
      return day
    })()
    loading.set(date, load)
    try {
      return await load
    } finally {
      loading.delete(date)
    }
  }

  /** Mark one day for the debounced writer. */
  function touch(date) {
    dirty.add(date)
    if (timer !== null) return
    timer = setTimeout(() => {
      timer = null
      void flush()
    }, FLUSH_DELAY_MS)
    timer.unref?.()
  }

  /** Write every dirty day atomically, one writer at a time. */
  async function flush() {
    const previous = writing
    const job = (async () => {
      if (previous !== null) await previous.catch(() => undefined)
      const dates = [...dirty]
      dirty.clear()
      if (dates.length === 0) return
      await mkdir(dataDir, { recursive: true })
      for (const date of dates) {
        const day = days.get(date)
        if (day === undefined) continue
        const target = join(dataDir, `${date}.json`)
        writeSeq += 1
        const temporary = `${target}.${process.pid}.${writeSeq}.tmp`
        await writeFile(temporary, `${JSON.stringify(day, null, 2)}\n`, 'utf8')
        await rename(temporary, target)
      }
    })()
    writing = job
    try {
      await job
    } catch (error) {
      warn('could not persist the work log', error)
    } finally {
      if (writing === job) writing = null
    }
  }

  /** One work item, created on demand from the session's current turn. */
  async function itemFor(session, turn, time) {
    const startedAt = time ?? Date.now()
    const day = await loadDay(localDay(startedAt))
    const id = `${session.id}#${turn}`
    let item = day.items[id]
    if (item === undefined) {
      item = {
        id,
        turn,
        sessionId: String(session.id),
        cwd: session.header.cwd ?? '',
        startedAt,
        updatedAt: startedAt,
        prompt: '',
        reply: '',
        messages: 0,
        folders: {},
        files: 0,
        added: 0,
        deleted: 0,
        fileList: [],
      }
      day.items[id] = item
    }
    return { day, item }
  }

  /** Whether a session belongs in the log (subagent work is folded into its parent). */
  function eligible(session) {
    const { origin, delegationDepth } = session.header
    if (origin === 'subagent' || (delegationDepth ?? 0) > 0) return false
    return true
  }

  /** Fold the change summary announced by one `workspace/changes` event. */
  function absorbChanges(session, event, state) {
    const service = ctx.get('workspaceChanges')
    if (service === undefined || typeof service.summary !== 'function') return
    let summary
    try {
      summary = service.summary(session.id, event.seq)
    } catch (error) {
      warn('workspace change summary unavailable', error)
      return
    }
    if (summary === undefined || !Array.isArray(summary.files)) return
    const turn = summary.turn ?? state.turn
    if (!turn) return
    void (async () => {
      const { day, item } = await itemFor(session, turn, state.startedAt ?? event.time)
      item.cwd = summary.cwd ?? item.cwd
      item.files = summary.total ?? summary.files.length
      item.added = summary.added ?? 0
      item.deleted = summary.deleted ?? 0
      item.fileList = summary.files.slice(0, MAX_FILES_IN_ITEM).map((file) => ({
        display: typeof file.display === 'string' ? file.display : String(file.path ?? ''),
        added: file.added ?? 0,
        deleted: file.deleted ?? 0,
      }))
      item.folders = {}
      for (const file of summary.files) {
        const folder = folderOf(file.path, item.cwd)
        item.folders[folder] = (item.folders[folder] ?? 0) + 1
      }
      item.updatedAt = event.time
      touch(day.date)
    })()
  }

  /** Fold one durable session event into the record. */
  function absorb(session, event) {
    if (!eligible(session)) return
    const id = String(session.id)
    let state = sessions.get(id)
    if (state === undefined) {
      state = { turn: 0, startedAt: undefined, prompt: '', reply: '', messages: 0 }
      sessions.set(id, state)
    }
    switch (event.type) {
      case 'turn/start': {
        state.turn = event.data.turn
        state.startedAt = event.time
        state.prompt = ''
        state.reply = ''
        state.messages = 0
        break
      }
      case 'user/message': {
        const source = event.data?.source
        if (source !== undefined && source.kind !== 'user') return
        const text = textOf(event.data?.content)
        if (text === '') return
        if (state.turn === 0) return
        state.messages += 1
        const first = state.prompt === ''
        if (first) state.prompt = text
        const turn = state.turn
        void (async () => {
          const { day, item } = await itemFor(session, turn, state.startedAt ?? event.time)
          if (first) item.prompt = clip(text, PROMPT_CHARS)
          item.messages = state.messages
          item.updatedAt = event.time
          touch(day.date)
        })()
        break
      }
      case 'assistant/message': {
        const text = textOf(event.data?.message?.content)
        if (text !== '') state.reply = text
        break
      }
      case 'workspace/changes': {
        absorbChanges(session, event, state)
        break
      }
      case 'turn/end': {
        const turn = event.data.turn
        if (!turn) break
        const reply = state.reply
        const messages = state.messages
        void (async () => {
          const { day, item } = await itemFor(session, turn, state.startedAt ?? event.time)
          if (reply !== '') item.reply = clip(reply, REPLY_CHARS)
          item.messages = messages
          item.endedAt = event.time
          item.updatedAt = event.time
          touch(day.date)
          void sampleBalance(false)
        })()
        break
      }
      default:
        break
    }
  }

  ctx.on('session/event', (session, event) => {
    try {
      absorb(session, event)
    } catch (error) {
      warn('could not record a session event', error)
    }
  })

  ctx.on('session/disposed', (session) => {
    sessions.delete(String(session.id))
  })

  // Capture the turns that already ran in this process, so installing the
  // plugin does not start with an empty page.
  ctx.effect(() => {
    const store = ctx.get('sessions')
    if (store === undefined || typeof store.list !== 'function') return
    const backfill = async () => {
      for (const session of store.list()) {
        try {
          if (!eligible(session)) continue
          const events = session.ownEvents()
          const window = events.slice(Math.max(0, events.length - BACKFILL_EVENTS))
          for (const event of window) absorb(session, event)
        } catch (error) {
          warn('could not backfill a live session', error)
        }
      }
      await flush()
    }
    void backfill()
  })

  ctx.effect(() => () => {
    if (timer !== null) clearTimeout(timer)
    timer = null
    void flush()
  })

  /**
   * The recharge wallet of a balance reply: CNY first, then USD, then whatever
   * the platform returned first. Wallets of the chosen currency are summed, so
   * a split wallet still reports one balance.
   */
  function walletOf(balance) {
    if (balance === null || balance === undefined) return undefined
    if (balance.status !== 'ready' || !Array.isArray(balance.value) || balance.value.length === 0) return undefined
    const wallets = balance.value.map((wallet) => ({ currency: wallet.currency, balance: wallet.balance }))
    const bonus = (balance.bonusWallets ?? []).map((wallet) => ({ currency: wallet.currency, balance: wallet.balance }))
    const primary = balance.value.find((wallet) => wallet.currency === 'CNY')
      ?? balance.value.find((wallet) => wallet.currency === 'USD')
      ?? balance.value[0]
    const currency = primary.currency === 'USD' ? 'USD' : 'CNY'
    let amount = 0
    let found = false
    for (const wallet of balance.value) {
      if (wallet.currency !== primary.currency) continue
      const value = Number(wallet.balance)
      if (!Number.isFinite(value)) continue
      amount += value
      found = true
    }
    if (!found) return undefined
    return { currency, amount, wallets, bonus }
  }

  /**
   * Read the wallet balance and fold today's spend from the day's opening balance.
   * A top-up raises the opening balance instead of producing negative spend.
   */
  async function sampleBalance(force) {
    if (balanceInFlight !== null) return balanceInFlight
    const now = Date.now()
    if (!force && now - lastBalanceAt < BALANCE_MIN_INTERVAL_MS) return
    const account = ctx.get('deepseekAccount')
    if (account === undefined || typeof account.getBalance !== 'function') return

    balanceInFlight = (async () => {
      let balance
      try {
        balance = await account.getBalance({
          version: process.env.DSH_CLIENT_VERSION ?? '0.0.0',
          locale: 'zh',
          timezoneOffsetSeconds: -new Date().getTimezoneOffset() * 60,
        })
      } catch (error) {
        warn('could not read the account balance', error)
        return
      }
      const wallet = walletOf(balance)
      if (wallet === undefined) return
      // Only a successful read opens the throttle window.
      lastBalanceAt = Date.now()
      const day = await loadDay(localDay(now))
      const previous = day.account
      // A rising balance is a recharge, not negative spend: keep it in topUps.
      const increase = previous === undefined ? 0 : Math.max(0, wallet.amount - previous.current)
      day.account = {
        currency: wallet.currency,
        opening: previous === undefined ? wallet.amount : previous.opening,
        current: wallet.amount,
        topUps: (previous?.topUps ?? 0) + increase,
        wallets: wallet.wallets,
        bonus: wallet.bonus,
        at: now,
      }
      touch(day.date)
      await flush()
    })()

    try {
      return await balanceInFlight
    } finally {
      balanceInFlight = null
    }
  }

  /** Read the day files that exist on disk, newest first. */
  async function knownDays(limit) {
    let names = []
    try {
      names = await readdir(dataDir)
    } catch {
      names = []
    }
    const dates = names
      .filter((entry) => /^\d{4}-\d{2}-\d{2}\.json$/.test(entry))
      .map((entry) => entry.slice(0, 10))
      .sort()
      .reverse()
    const today = localDay(Date.now())
    if (days.has(today) && !dates.includes(today)) dates.unshift(today)
    return dates.slice(0, Math.max(1, limit))
  }

  /** The page/tool payload for one requested day: projects, durations, summaries. */
  async function payload(requested, dayCount, forceBalance) {
    const today = localDay(Date.now())
    const target = /^\d{4}-\d{2}-\d{2}$/.test(requested) ? requested : today
    await Promise.race([
      sampleBalance(forceBalance === true).catch(() => undefined),
      new Promise((resolve) => {
        const id = setTimeout(resolve, 2500)
        id.unref?.()
      }),
    ])
    await flush()
    const available = await knownDays(dayCount)
    const dates = [...new Set([target, today, ...available])].sort().reverse()
    const day = await loadDay(target)
    return {
      today,
      date: target,
      day: dayView(day),
      days: dates.slice(0, Math.max(1, dayCount)),
    }
  }

  /** One project's summary prompt: the day's requests and conclusions, nothing else. */
  function summaryPrompt(day, projectKey) {
    const items = Object.values(day.items)
      .filter((item) => (item.cwd === '' ? UNKNOWN_PROJECT : item.cwd) === projectKey)
      .sort((left, right) => left.startedAt - right.startedAt)
    const name = projectKey === UNKNOWN_PROJECT ? UNKNOWN_PROJECT : basename(projectKey) || projectKey
    const lines = items.map((item, index) => {
      const folders = Object.keys(item.folders ?? {}).slice(0, 6).join('、')
      const parts = [`${index + 1}. ${clockTime(item.startedAt)} 请求：${clip(item.prompt, 300) || '（未记录）'}`]
      if (item.reply !== '') parts.push(`   结论：${clip(item.reply, 400)}`)
      if (folders !== '') parts.push(`   改动：${folders}（${item.files} 个文件，+${item.added}/-${item.deleted}）`)
      return parts.join('\n')
    })
    return {
      project: name,
      cwd: projectKey,
      turns: items.length,
      text: [
        `项目：${name}`,
        `工作目录：${projectKey}`,
        `今天的 ${items.length} 轮工作记录：`,
        '',
        lines.join('\n\n'),
      ].join('\n'),
    }
  }

  /** Ask the configured model to compress one project's day into 1-4 lines. */
  async function generateSummary(date, projectKey, force) {
    const key = `${date}|${projectKey}`
    const running = summarizing.get(key)
    if (running !== undefined) return running

    const task = (async () => {
      const day = await loadDay(date)
      const { project, turns, text } = summaryPrompt(day, projectKey)
      if (turns === 0) throw new Error('这一天在这个项目上没有记录')
      const current = day.summaries?.[projectKey]
      if (!force && current !== undefined && current.turns === turns) return current

      const llm = ctx.get('llm')
      if (llm === undefined || typeof llm.stream !== 'function') {
        throw new Error('当前没有可用的模型适配器')
      }
      const selection = ctx.get('agentDefaultModel')?.currentSelection?.()
      if (selection === undefined) throw new Error('没有可用的默认模型')

      const controller = new AbortController()
      const timeout = setTimeout(() => controller.abort(), SUMMARY_TIMEOUT_MS)
      timeout.unref?.()
      const stream = llm.stream({
        signal: controller.signal,
        provider: selection.provider,
        model: selection.model,
        system: [
          '你在为一份「工作日志」写当日摘要，读者是这位工程师本人。',
          '只概括“今天在这个项目上解决了什么问题、做完了什么”，动词开头，具体但不啰嗦。',
          '禁止复述对话，禁止出现文件路径、函数名、代码片段，禁止“用户要求/我完成了”这类叙述腔。',
          '输出 1-4 行，每行以「- 」开头，每行不超过 40 个汉字。不要输出标题、编号、解释或代码块。',
        ].join('\n'),
        messages: [{ role: 'user', content: [{ type: 'text', text }] }],
        maxTokens: SUMMARY_MAX_TOKENS,
        temperature: 0.3,
      })

      let raw = ''
      let blockText = ''
      let failure
      let reason = ''
      try {
        for await (const chunk of stream) {
          if (chunk.type === 'text-delta') raw += chunk.text
          else if (chunk.type === 'block-end' && chunk.block?.type === 'text') blockText += chunk.block.text
          else if (chunk.type === 'finish') {
            reason = chunk.reason.kind
            if (chunk.reason.kind === 'error' || chunk.reason.kind === 'aborted') failure = chunk.reason.failure
          }
        }
      } finally {
        clearTimeout(timeout)
      }
      if (controller.signal.aborted && failure === undefined) {
        throw new Error(`模型调用超时（${SUMMARY_TIMEOUT_MS / 1000} 秒）`)
      }
      if (failure !== undefined) throw new Error(failure.message ?? '模型调用失败')
      if (raw.trim() === '' && blockText !== '') raw = blockText
      if (raw.trim() === '') throw new Error(`模型没有返回内容（finish=${reason || 'none'}）`)

      const bullets = raw
        .split('\n')
        .map((line) => line.replace(/^\s*(?:[-*•]|\d+[.)])\s*/, '').trim())
        .filter((line) => line !== '' && !line.startsWith('```'))
        .slice(0, 4)
      if (bullets.length === 0) throw new Error('模型没有返回可用的摘要')

      const summary = { bullets, at: Date.now(), turns, source: 'model' }
      day.summaries = day.summaries ?? {}
      day.summaries[projectKey] = summary
      touch(date)
      await flush()
      ctx.logger?.info?.(`work-log: summarized ${project} (${date})`)
      return summary
    })()

    summarizing.set(key, task)
    try {
      return await task
    } finally {
      summarizing.delete(key)
    }
  }

  // ── page routes ────────────────────────────────────────────────────────────

  /**
   * Reject anything that is not a loopback, same-origin request: these routes
   * expose the wallet balance and can spend model quota.
   */
  function rejectRoute(req, res) {
    const address = req.socket?.remoteAddress
    const local = address === '127.0.0.1' || address === '::1' || address === '::ffff:127.0.0.1'
    if (!local) {
      res.writeHead(403, { 'content-type': 'application/json; charset=utf-8' })
      res.end(JSON.stringify({ error: 'local access only' }))
      return true
    }
    const origin = req.headers?.origin
    if (typeof origin === 'string' && origin !== '') {
      let host
      try {
        host = new URL(origin).host
      } catch {
        host = undefined
      }
      if (host === undefined || host !== req.headers?.host) {
        res.writeHead(403, { 'content-type': 'application/json; charset=utf-8' })
        res.end(JSON.stringify({ error: 'cross-origin request rejected' }))
        return true
      }
    }
    return false
  }

  // The web server may still be listening when this row activates at boot, so a
  // plain ctx.get() would silently skip every route. Wait for the service.
  ctx.inject(['webServer'], (web) => {
    const webServer = web.webServer
    web.effect(() => webServer.register({
      kind: 'exact',
      path: '/work-log/data.json',
      handler: async (req, res) => {
        if (rejectRoute(req, res)) return
        try {
          const url = new URL(req.url ?? '/', 'http://localhost')
          const requested = url.searchParams.get('date') ?? ''
          const dayCount = Number(url.searchParams.get('days') ?? DEFAULT_DAYS)
          const fresh = url.searchParams.get('fresh') === '1'
          const body = await payload(
            requested,
            Number.isFinite(dayCount) ? Math.min(90, Math.max(1, dayCount)) : DEFAULT_DAYS,
            fresh,
          )
          res.writeHead(200, {
            'content-type': 'application/json; charset=utf-8',
            'cache-control': 'no-store',
          })
          res.end(JSON.stringify(body))
        } catch (error) {
          warn('could not answer the work log route', error)
          res.writeHead(500, { 'content-type': 'application/json; charset=utf-8' })
          res.end(JSON.stringify({ error: 'work log unavailable' }))
        }
      },
    }))

    ctx.effect(() => webServer.register({
      kind: 'exact',
      path: '/work-log/month.json',
      handler: async (req, res) => {
        if (rejectRoute(req, res)) return
        try {
          const url = new URL(req.url ?? '/', 'http://localhost')
          const raw = url.searchParams.get('month') ?? ''
          const month = /^\d{4}-\d{2}$/.test(raw) ? raw : localDay(Date.now()).slice(0, 7)
          await flush()
          const [year, mon] = month.split('-').map(Number)
          const total = new Date(year, mon, 0).getDate()
          const days = {}
          for (let day = 1; day <= total; day += 1) {
            const date = `${month}-${String(day).padStart(2, '0')}`
            const record = await loadDay(date)
            if (Object.keys(record.items).length === 0) continue
            const view = dayView(record)
            days[date] = { ms: view.totalMs, projects: view.totals.projects, turns: view.totals.turns }
          }
          res.writeHead(200, {
            'content-type': 'application/json; charset=utf-8',
            'cache-control': 'no-store',
          })
          res.end(JSON.stringify({ month, days }))
        } catch (error) {
          warn('could not answer the work log calendar route', error)
          res.writeHead(500, { 'content-type': 'application/json; charset=utf-8' })
          res.end(JSON.stringify({ error: 'calendar unavailable' }))
        }
      },
    }))

    ctx.effect(() => webServer.register({
      kind: 'exact',
      path: '/work-log/summarize.json',
      handler: async (req, res) => {
        if (rejectRoute(req, res)) return
        const respond = (status, body) => {
          res.writeHead(status, {
            'content-type': 'application/json; charset=utf-8',
            'cache-control': 'no-store',
          })
          res.end(JSON.stringify(body))
        }
        try {
          if (req.method !== 'POST') return respond(405, { ok: false, error: 'POST only' })
          const chunks = []
          let bytes = 0
          for await (const chunk of req) {
            bytes += chunk.length
            if (bytes > MAX_BODY_BYTES) return respond(413, { ok: false, error: 'payload too large' })
            chunks.push(chunk)
          }
          const body = JSON.parse(Buffer.concat(chunks).toString('utf8') || '{}')
          const date = /^\d{4}-\d{2}-\d{2}$/.test(body.date ?? '') ? body.date : localDay(Date.now())
          const project = String(body.project ?? '')
          if (project === '') return respond(400, { ok: false, error: 'project is required' })
          const summary = await generateSummary(date, project, body.force === true)
          return respond(200, { ok: true, date, project, summary })
        } catch (error) {
          warn('could not summarize a project', error)
          return respond(502, {
            ok: false,
            error: error instanceof Error ? error.message : String(error),
          })
        }
      },
    }))
  })

  // ── model-facing tool ──────────────────────────────────────────────────────
  ctx.tools.register({
    name: 'work_log',
    description:
      'Read or annotate the user\'s daily work log (工作日志). The log folds every top-level turn into a work item, groups items by project (working directory), and keeps each project\'s duration, changed folders/files, and a short "what got solved" summary. The panel never renders raw conversation. Use action "read" to answer what the user worked on and for how long, "summarize" to write a project summary yourself (it replaces the generated one), and "record" to append a manual note.',
    parameters: {
      action: {
        type: 'string',
        required: true,
        enum: ['read', 'record', 'summarize', 'refresh'],
        description: 'read: projects, durations, and summaries. record: append a note. summarize: replace one project\'s summary with text you write. refresh: ask the model to regenerate summaries (one project, or every project of the day).',
      },
      date: {
        type: 'string',
        description: 'Local calendar day as YYYY-MM-DD. Defaults to today.',
      },
      project: {
        type: 'string',
        description: 'Project key: the working directory reported by action "read". Required for action "summarize".',
      },
      text: {
        type: 'string',
        description: 'Note text for "record", or the summary lines for "summarize" (one line per bullet).',
      },
      folders: {
        type: 'array',
        description: 'Folders a note refers to, relative paths such as "site/css".',
        items: { type: 'string' },
      },
    },
    output: {
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          date: { type: 'string' },
          projects: { type: 'integer' },
          totalMs: { type: 'integer' },
          text: { type: 'string' },
        },
        required: ['date', 'projects', 'totalMs', 'text'],
      },
      render: (_args, value) => [{ type: 'text', text: value.text }],
    },
    presentCall: (args) => ({
      card: 'generic',
      title: args.action === 'read' ? 'Read the work log' : args.action === 'record' ? 'Append to the work log' : 'Summarize a project',
      kind: 'other',
      rawInput: args,
    }),
    async execute(args) {
      const today = localDay(Date.now())
      const date = /^\d{4}-\d{2}-\d{2}$/.test(args.date ?? '') ? args.date : today
      const day = await loadDay(date)

      if (args.action === 'record') {
        const text = String(args.text ?? '').trim()
        if (text === '') throw new Error('work_log record requires non-empty text')
        day.notes.push({
          id: `note-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`,
          time: Date.now(),
          text: clip(text, 400),
          folders: (args.folders ?? []).map((folder) => String(folder)).filter((folder) => folder !== ''),
        })
        touch(date)
        await flush()
      }

      if (args.action === 'refresh') {
        const keys = [...new Set(Object.values(day.items)
          .map((item) => (item.cwd === '' ? UNKNOWN_PROJECT : item.cwd)))]
        const wanted = args.project === undefined || args.project === ''
          ? keys
          : keys.filter((key) => key === args.project || basename(key) === args.project)
        if (wanted.length === 0) throw new Error('这一天没有可总结的项目')
        for (const key of wanted) {
          try {
            await generateSummary(date, key, true)
          } catch (error) {
            throw new Error(`刷新 ${key} 失败：${error instanceof Error ? error.message : String(error)}`)
          }
        }
      }

      if (args.action === 'summarize') {
        const project = String(args.project ?? '')
        if (project === '') throw new Error('work_log summarize requires a project')
        const bullets = String(args.text ?? '')
          .split('\n')
          .map((line) => line.replace(/^\s*(?:[-*•]|\d+[.)])\s*/, '').trim())
          .filter((line) => line !== '')
          .slice(0, 4)
        if (bullets.length === 0) throw new Error('work_log summarize requires at least one line of text')
        const current = dayView(day).projects.find((candidate) => candidate.key === project || candidate.name === project)
        const turns = current === undefined ? 0 : current.turns
        day.summaries = day.summaries ?? {}
        day.summaries[project] = { bullets, at: Date.now(), turns, source: 'agent' }
        touch(date)
        await flush()
      }

      const view = dayView(day)
      const lines = [`${date} · ${formatDuration(view.totalMs)} · ${view.totals.projects} 个项目`]
      for (const project of view.projects) {
        const meta = [
          formatDuration(project.ms),
          `${project.turns} 轮`,
          project.files > 0 ? `${project.files} 个文件 +${project.added}/-${project.deleted}` : '无文件改动',
        ].join('，')
        lines.push('', `${project.name}（${meta}）`)
        lines.push(`  目录：${project.key}`)
        if (project.summary === null) {
          lines.push('  摘要：（还没有摘要，可以用 action "summarize" 写一条）')
        } else {
          for (const bullet of project.summary.bullets) lines.push(`  - ${bullet}`)
          if (project.summary.stale) lines.push('  （摘要之后又有新的工作）')
        }
        if (project.folders.length > 0) {
          lines.push(`  文件夹：${project.folders.slice(0, 8).map((folder) => `${folder.path}(${folder.files})`).join('、')}`)
        }
      }
      for (const note of view.notes.slice(0, 10)) {
        lines.push('', `备注 ${clockTime(note.time)}：${note.text}`)
      }
      return {
        date,
        projects: view.totals.projects,
        totalMs: view.totalMs,
        text: lines.join('\n'),
      }
    },
  })
}

export { apply, inject, name }
